+export async function countMatches(
+  pattern: string,
+  directory: string,
+): Promise<number> {
+  return new Promise((resolve, reject) => {
+    execFile(
+      "rg",
+      ["--count", "--no-filename", "--", pattern, directory],
+      (error, stdout) => {
+        if (error && error.code !== 1) {
+          reject(error);
+          return;
+        }
+
+        resolve(
+          stdout
+            .trim()
+            .split(/\s+/)
+            .filter(Boolean)
+            .reduce((total, count) => total + Number(count), 0),
+        );
+      },
+    );
+  });
+}
